const head=(t,d,x='')=>`<div class="top"><div class="tl">${me?`<button id="navBtn" class="nb" onclick="toggleNav()" aria-controls="nav" aria-expanded="${!navOff}" title="${navOff?'Hiện thanh menu':'Ẩn thanh menu'}"><i></i><i></i><i></i></button>`:''}<div><h2>${t}</h2><p>${d}</p></div></div><div class="row">${x}${me?`<button class="s" id="bell" onclick="notesM()">🔔 Thông báo${S.notes.length>noteSeen?` <span class="cnt">${S.notes.length-noteSeen}</span>`:''}</button>`:''}<button class="s" onclick="tt()">◐ Sáng/Tối</button>${me?'<button class="s" onclick="logout()">← Chọn lại vai trò</button>':''}</div></div>`+(PHMAP[cur]===null?'':phB(cur));
const tbl=(h,rows)=>`<div class="tw"><table><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan=${h.length} style="color:var(--mu)">Chưa có dữ liệu</td></tr>`}</table></div>`;
const st=(ok,t,d='')=>`<div class="step ${ok}"><b>${ok=='ok'?'✔':ok=='er'?'✖':'…'}</b><div><b>${t}</b><div style="color:var(--mu)">${d}</div></div></div>`;
const bars=(a,f=x=>x)=>{const m=Math.max(0,...a.map(x=>x[1]))||1;return a.map(([l,v])=>`<div class="bar"><span style="width:64px;color:var(--mu)">${l}</span><i style="width:${Math.max(2,v/m*60)}%"></i><b>${f(v)}</b></div>`).join('')};

/* DASH */
P.dash=()=>{const l=live(),rev=S.pays.reduce((a,x)=>a+x.amt,0)+ 8420000;
return head('Bảng điều khiển','Tình hình vận hành cổng hôm nay')+heroH()+strip()+`<div class="g g4"><div class="c k"><b>${l.length}</b><span>Xe đang trong bãi</span></div><div class="c k"><b>${vnd(rev)}</b><span>Doanh thu hôm nay</span></div><div class="c k"><b>${S.exc.filter(e=>e.kind.startsWith('Mở')).length}</b><span>Lượt mở barrier thủ công</span></div><div class="c k"><b>${S.lots.filter(x=>x.ex&&x.reg&&!x.used).length}/${S.lots.length}</b><span>Lô hàng đủ điều kiện vào</span></div></div>
<div class="g g2 mt"><div class="c"><h3>Xe đang trong bãi</h3>${tbl(['Biển số','Loại xe','Giờ vào','Trạng thái'],l.map(s=>[s.plate,s.type,fmt(s.inAt),tag(s.st,s.st=='Đang đỗ'?'wa':'ok')]))}</div>
<div class="c"><h3>Kết nối hệ thống</h3>${S.dev.map(d=>st(d.st=='Online'?'ok':'er',d.n,d.st+' · '+d.ip)).join('')}</div></div>
<div class="g g2 mt"><div class="c"><h3>Hàng chờ xử lý</h3>${queue()}</div><div class="c"><h3>Thông báo gần đây</h3>${noteTbl(S.notes.slice(0,6))}<div class="row mt"><button class="s" onclick="notesM()">Xem tất cả thông báo</button></div></div></div>`};
const queue=()=>{const q=S.qr.filter(x=>x.st=='pending'),pl=S.lots.filter(l=>l.pend),hold=live().filter(x=>owe(x)>0&&S.alerts.some(a=>a.plate==x.plate)),ov=live().filter(x=>x.st=='Đã thanh toán'&&owe(x)>0),go2=(k,t)=>can(k)?`<button class="s" onclick="go('${k}')">${t}</button>`:'';return st(q.length?'wa':'ok','Giao dịch QR chờ ngân hàng xác nhận',q.length?q.map(x=>x.plate+' · '+vnd(x.amt)).join(', '):'Không có')+st(pl.length?'wa':'ok','Lô hàng chờ COSYS phản hồi',pl.length?pl.map(l=>l.id+' · '+l.plate).join(', '):'Không có')+st(hold.length?'er':'ok','Xe bị giữ ở lane ra do chưa thanh toán',hold.length?hold.map(x=>x.plate+' · còn '+vnd(owe(x))).join(', '):'Không có')+st(ov.length?'er':'ok','Xe quá '+GRACE+' phút sau thanh toán chưa ra',ov.length?ov.map(x=>x.plate+' · phát sinh '+vnd(owe(x))).join(', '):'Không có')+`<div class="row mt">${go2('pay','Mở quầy thu ngân')}${go2('lots','Mở danh mục lô hàng')}${go2('alert','Xem cảnh báo')}</div>`};

/* LANE VÀO */

/* ===== Kết quả xử lý lane: ảnh camera ANPR ===== */
const VEH={'Xe tải nhỏ':1,'Xe bán tải':4,'Xe container':3};
/* vị trí biển số trong từng ảnh xe (% trái, % trên, % rộng, % cao, màu nền) */
const PLP={1:[10.3,74.6,6.9,6.6,''],2:[64.8,84.6,5.4,3.9,''],3:[10.2,67.7,4.4,3.9,'y'],4:[67.7,84.6,8.6,6,'']};
const tsF=()=>new Date().toLocaleString('vi-VN',{hour12:false});
const conf=p=>94+[...p].reduce((a,c)=>a+c.charCodeAt(0),0)%6;
const snap=(k,p,type,ok,body,o={})=>{const v=type?VEH[type]||1:2,[x,y,w,h,c]=PLP[v],cam=k=='in'?'CAM-IN-01 · Lane vào 1':'CAM-OUT-01 · Lane ra 1',
cf=o.nf?'—':conf(p)+'%',vc=ok?'':o.pend?'wa':'er',vt=ok?(k=='in'?'ĐỦ ĐIỀU KIỆN · MỞ BARRIER':'CHO XE RA · MỞ BARRIER'):o.pend?'CHỜ XÁC NHẬN · GIỮ BARRIER':'KHÔNG ĐẠT · GIỮ BARRIER',
vs=ok?(k=='in'?'Đã tạo phiên đỗ và bắt đầu tính phí bãi':'Đã đóng phiên, lưu ảnh check-out'):(o.why||'Bảo vệ xử lý theo quy trình');
return `<div class="snap"><img src="assets/img/photos/vehicles/veh-${v}.jpg" alt="Ảnh camera chụp xe ${p}">
<div class="hud"><span class="rec">${cam}</span><span>${tsF()}</span></div>
<span class="lp ${c}" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%"><b style="font-size:${(w*0.19).toFixed(2)}cqw">${p}</b></span>
<span class="bb ${vc}" style="left:${x-1.2}%;top:${y-2.2}%;width:${w+2.4}%;height:${h+4.4}%"><i>ANPR ${p} · ${cf}</i></span>
</div><div class="verdict ${vc}"><span class="ic">${ok?'✔':o.pend?'…':'✖'}</span><div>${vt}<small>${vs}</small></div></div>
<div class="meta"><div><small>Biển số nhận diện</small><b>${p}</b></div><div><small>Loại xe</small><b>${type||'Chưa phân loại'}</b></div><div><small>Độ tin cậy ANPR</small><b>${cf}</b></div><div><small>Barrier</small><b style="color:var(--${ok?'ok':o.pend?'wa':'er'})">${ok?'Đang mở':'Giữ đóng'}</b></div></div>
<div class="shots"><div class="shot"><div class="im">${plSvg(p)}</div><span>Ảnh biển số <b>${k=='in'?'Check-in':'Check-out'}</b></span></div>
<div class="shot">${k=='out'?`<div class="im f2"><div>${faceSvg()}<i>Lúc vào</i></div><div>${faceSvg()}<i>Lúc ra</i></div></div><span>Tài xế <b>Bảo vệ quan sát</b></span>`:`<div class="im">${faceSvg()}</div><span>Tài xế <b>Đã chụp</b></span>`}</div>
<div class="shot"><div class="im"><div class="bar2 ${ok?'ok':vc}">${ok?'▲ BARRIER MỞ':'■ BARRIER ĐÓNG'}</div></div><span>Trạng thái <b>${k=='in'?'Lane vào':'Lane ra'}</b></span></div></div>
<h3 class="mt">Các bước kiểm tra</h3>${body}`};
const waitR=k=>`<div class="snap wait"><img src="assets/img/photos/lane-${k}.jpg" alt="Lane ${k=='in'?'vào':'ra'} đang chờ xe"><div class="hud"><span class="rec">${k=='in'?'CAM-IN-01 · Lane vào 1':'CAM-OUT-01 · Lane ra 1'}</span><span>LIVE</span></div><div class="radar"></div><div class="wt"><b>Đang chờ xe vào vùng nhận diện…</b><span>Radar sẵn sàng · Camera ANPR online · Barrier đóng</span></div></div>
<div class="pipe">${(k=='in'?[['Radar','Phát hiện xe'],['Camera AI','Đọc biển số'],['COSYS','Đối chiếu lô hàng'],['Barrier','Mở / giữ']]:[['Camera AI','Đọc biển số'],['Phiên vào','Đối chiếu'],['Thanh toán','Kiểm tra phí'],['Barrier','Mở / giữ']]).map(([a,b])=>`<span><b>${a}</b>${b}</span>`).join('')}</div>`;
let inR=null;
P.in=()=>{const opts=[...new Set(S.lots.filter(l=>!live().some(s=>s.plate==l.plate)).map(l=>l.plate))].map(p=>`<option>${esc(p)}</option>`).join('')+'<option>29A-999.99</option>';
return head('Kiểm soát lane vào','Radar → Camera AI đọc biển số → đối chiếu COSYS → barrier')+`<div class="g g2"><div class="c"><h3>Mô phỏng xe tiến vào lane</h3><label>Biển số camera đọc được</label><div class="row"><select id="ip">${opts}</select><button onclick="scanIn()">Radar phát hiện xe</button></div><p style="color:var(--mu)">Thử: 51C-123.45, 51C-660.44 (đạt), 43C-357.91 (chờ COSYS xác nhận), 60C-555.12 (chưa xuất kho), 61C-246.80 (chưa đăng ký), 51C-777.88 (loại xe không khớp đăng ký), 29A-999.99 (không có trong COSYS). Xe đang đỗ trong bãi không hiển thị trong danh sách.</p><div class="mt">${pic('lane-in',laneSvg('in'),'Camera lane vào 1')}</div><div style="margin-top:12px">Barrier lane vào</div><div class="gate ${S.lane.in?'open':''}"></div></div>
<div class="c"><h3>Kết quả xử lý</h3>${inR?inR:waitR('in')}</div></div>
<div class="c mt"><h3>Lượt vào gần đây</h3>${tbl(['Mã phiên','Biển số','Lô hàng','Giờ check-in','Trạng thái'],S.sess.slice().reverse().slice(0,6).map(s=>[s.id,s.plate,s.lot,fmt(s.inAt),tag(s.st)+(s.exIn||s.exOut?' '+tag('Ngoại lệ','er'):'')]))}</div>`};
window.newSess=(p,l,ex)=>S.sess.push({id:'PH-'+String(S.sess.length+1).padStart(4,'0'),plate:p,lot:l?l.id:'—',type:l?l.type:TYPES[0],inAt:now(),st:'Đang đỗ',paid:0,due:0,ch:'',exIn:ex,imgIn:1});
window.scanIn=()=>{const p=$('#ip').value,l=lotBy(p),det=l?(l.det||l.type):null,mis=l&&det!=l.type,used=l&&l.used,ok=l&&l.reg&&l.ex&&!mis&&!used;
let h=st('ok','Radar phát hiện xe · Camera AI đọc biển số',plate(p)+' · '+(det||'Chưa phân loại')+' · đã chụp ảnh biển số và khuôn mặt tài xế')+st(l&&l.reg?'ok':'er','Đăng ký nhận hàng trên Web',l?(l.reg?'Đã đăng ký – '+l.driver:'Chưa đăng ký'):'Không tìm thấy biển số')+st(l&&l.ex?'ok':l&&l.pend?'wa':'er','Lô hàng đã xuất kho (COSYS)',l?(l.ex?l.id+' – Đã xuất':l.pend?l.id+' – Đang chờ COSYS phản hồi trạng thái xuất kho':l.id+' – Chưa xuất'):'Không có lô hàng');
if(l)h+=st(mis?'er':'ok','Loại xe khớp thông tin đăng ký',mis?'Camera AI nhận diện: '+det+' · Đăng ký: '+l.type+' – sai loại xe, ảnh hưởng tính phí và vị trí dock':'Camera AI nhận diện: '+det+' · khớp đăng ký');
if(used)h+=st('er','Lô hàng đã nhận xong','Lô '+l.id+' đã hoàn tất, xe không được vào lại bằng lô này');
const pend=!!(l&&l.pend&&!l.ex&&l.reg&&!mis&&!used),why=ok?'':(!l?'Không có lô hàng / đăng ký':!l.reg?'Chưa đăng ký nhận hàng':pend?'Chờ COSYS xác nhận xuất kho':!l.ex?'Lô hàng chưa xuất kho':mis?'Loại xe không khớp đăng ký':'Lô hàng đã nhận xong');
if(ok){newSess(p,l,false);S.lane.in=1;clearTimeout(S.lane.ti);S.lane.ti=setTimeout(()=>{S.lane.in=0;if(cur=='in')R()},2500);h+=st('ok','Đủ điều kiện – tự động mở barrier','Đã lưu ảnh check-in, ghi mốc giờ vào và bắt đầu tính phí bãi');note('ok','Xe vào thành công',p+' · lô '+l.id)}
else if(pend){h+=st('wa','Chờ xác nhận – barrier giữ đóng','Hướng dẫn xe vào làn chờ; truy vấn lại COSYS rồi cho xe quét lại')+`<div class="row mt"><button onclick="cosysRe('${l.id}')">Truy vấn lại COSYS</button><button class="s" onclick="turnIn('${p}','${why}')">Hướng dẫn quay đầu</button></div>`;note('wa','Xe vào chờ xác nhận',p+' · lô '+l.id+' chờ COSYS')}
else{note('er','Xe vào bị từ chối',p+' · '+why);h+=st('er','Không đủ điều kiện – barrier giữ đóng','Bảo vệ hướng dẫn xe quay đầu; chỉ khi được cấp thẩm quyền mới mở thủ công')+`<div class="row mt"><button class="s" onclick="turnIn('${p}','${why}')">Hướng dẫn quay đầu</button><button class="d" onclick="manual('${p}','vào')">Mở barrier thủ công</button></div>`}
S.last.in=p;inR=snap('in',p,det,ok,h,{nf:!l,why,pend});R()};
window.cosysRe=id=>{const l=S.lots.find(x=>x.id==id);if(!l)return;l.pend=0;l.ex=1;l.sync='Đã đồng bộ';S.lots.sy=now();S.api.unshift({t:now(),sys:'COSYS',ip:'10.10.1.5',ok:true,msg:'Phản hồi '+id+': đã xuất kho'});note('ok','COSYS xác nhận xuất kho',id+' · '+l.plate);inR=null;R();popup('ok','COSYS đã xác nhận',`Lô ${id} (${esc(l.plate)}) đã xuất kho.`,['Cho xe quét lại tại lane vào để mở barrier'])};
window.turnIn=(p,w)=>{note('er','Xe quay đầu tại lane vào',p+' · '+w);S.exc.unshift({t:now(),who:me&&me.r!='Thu ngân quầy'?me.u:'baove01',lane:'Lane vào 1',plate:p,why:w,kind:'Quay đầu (lane vào)'});inR=null;R();toast('Đã ghi nhật ký xe quay đầu')};
window.manual=(p,d)=>{modal(`<h3>Mở barrier thủ công (remote) – ${d}</h3><p>Biển số ${plate(p)}</p><label>Người thực hiện</label><select id="mg">${S.users.filter(u=>u.on&&u.r!='Thu ngân quầy').map(u=>`<option value="${esc(u.u)}" ${me&&u.u==me.u?'selected':''}>${esc(u.u)} · ${u.r}</option>`).join('')}</select><label>Lý do cưỡng chế (bắt buộc)</label><textarea id="mw" rows=3 style="width:100%"></textarea><div class="row mt"><button onclick="doManual('${p}','${d}')">Xác nhận & ghi log</button><button class="s" onclick="cm()">Hủy</button></div>`)};
const oweT=s=>s.payAt&&now()-s.payAt<=GRACE*6e4?s.payAt:now();
window.owe=s=>Math.max(0,feeOf(s,oweT(s)).tot-s.paid);
window.doManual=(p,d)=>{const w=$('#mw').value.trim();if(!w)return toast('Cần nhập lý do');const l=lotBy(p);let debt=0;
if(d=='vào'){if(!live().find(s=>s.plate==p))newSess(p,l,true)}
else{const s=live().find(x=>x.plate==p);if(s){debt=owe(s);s.st='Đã đóng';s.outAt=now();s.exOut=true;s.debt=debt;const ls=lotOf(s);if(ls)ls.used=true}}
S.exc.unshift({t:now(),who:$('#mg').value,lane:'Lane '+d+' 1',plate:p,why:w+(debt?' – chưa thu '+vnd(debt):''),kind:'Mở barrier thủ công ('+d+')'});note('wa','Mở barrier thủ công lane '+d,p+(debt?' · chưa thu '+vnd(debt):'')+' · '+w);inR=null;outR=null;cm();R();toast('Đã mở barrier, lưu ảnh camera và ghi log ngoại lệ')};

/* THU NGÂN */
let cs=null,qr=0;
const qrSvg=s=>{let x=0;for(const c of s)x=(x*31+c.charCodeAt(0))%1e9;let r='';for(let i=0;i<19;i++)for(let j=0;j<19;j++){x=(x*1103515245+12345)%2147483648;if(x%3<1||(i<4&&j<4)||(i<4&&j>14)||(i>14&&j<4))r+=`<rect x=${j*6} y=${i*6} width=6 height=6 />`}return`<svg viewBox="0 0 114 114" width=170 style="background:#fff;padding:6px;border-radius:6px" fill="#111">${r}</svg>`};
P.pay=()=>{const s=cs&&S.sess.find(x=>x.id==cs),unp=live().filter(x=>x.st=='Đang đỗ');
let body='<p style="color:var(--mu)">Nhập biển số hoặc quét mã kiện hàng để tra cứu.</p>';
if(s){const open=s.st=='Đang đỗ',f=open?feeOf(s):{m:Math.ceil(((s.payAt||s.outAt||now())-s.inAt)/6e4),base:0,su:[],sf:0,tot:s.due},left=open?Math.max(0,f.tot-s.paid):0;
body=`<div class="row">${plate(s.plate)} ${tag(s.st,s.st=='Đang đỗ'?'wa':'ok')}</div><p>Lô hàng ${s.lot} · ${s.type}<br>Giờ vào: ${fmt(s.inAt)}<br>${open?'Giờ hiện tại: '+fmt(now()):'Giờ thanh toán: '+fmt(s.payAt)}<br>Thời gian đỗ${open?'':' (đến lúc thanh toán)'}: <b>${dur(f.m)}</b></p>${open&&f.np?`<p class="tg er">Chưa có khung giá cho ${s.type} với thời gian đỗ này – cần bổ sung bảng giá trước khi thu</p>`:''}
<table>${open?`<tr><td>Phí đỗ (${s.type})</td><td>${vnd(f.base)}</td></tr>${f.su.map(x=>`<tr><td>${esc(x.name)} (>${x.after} phút)</td><td>${vnd(x.fee)}</td></tr>`).join('')}`:''}<tr><td><b>Phải thu</b></td><td><b>${vnd(f.tot)}</b></td></tr><tr><td>Đã thanh toán</td><td>${vnd(s.paid)}</td></tr><tr><td><b>Còn lại</b></td><td><b style="color:var(--${left?'er':'ok'})">${vnd(left)}</b></td></tr></table>`;
if(open&&s.pend){const q=S.qr.find(x=>x.ref==s.pend);body+=`<div class="step wa mt"><b>…</b><div><b>Giao dịch QR ${q.ref} đang chờ ngân hàng xác nhận</b><div style="color:var(--mu)">${vnd(q.amt)} · gửi lúc ${fmt(q.t)}. Không thu tiếp cho đến khi có kết quả tra soát.</div></div></div><div class="row mt"><button onclick="qrRes('${q.ref}',1)">Tra soát: ngân hàng xác nhận</button><button class="s" onclick="qrRes('${q.ref}',0)">Tra soát: giao dịch thất bại</button></div>`}
else if(open&&!f.np){body+=`<div class="row mt"><button class="${S.tab=='QR'?'':'s'}" onclick="S.tab='QR';qr=0;R()">QR VietQR/VNPay</button><button class="${S.tab=='Cash'?'':'s'}" onclick="S.tab='Cash';R()">Tiền mặt</button></div>`;
if(S.tab=='QR')body+=`<div class="mt">${qrSvg(s.id+f.tot)}<p>Số tiền: <b>${vnd(left)}</b> · Mã GD: QR${s.id.slice(3)}${Math.floor(f.tot/1000)}</p><div class="row"><button onclick="bank('${s.id}',1,${left})">Mô phỏng: thành công</button><button class="s" onclick="bank('${s.id}',0,${left})">Thất bại</button><button class="s" onclick="bank('${s.id}',2,${left})">Chờ xác nhận</button></div></div>`;
else body+=`<label>Tiền khách đưa</label><input id="cash" type=number value="${Math.ceil(left/1e4)*1e4}" oninput="chg(${left})"><p>Tiền thừa: <b id="chg">${vnd(Math.ceil(left/1e4)*1e4-left)}</b></p><button onclick="cashPay('${s.id}',${left})">Xác nhận thu tiền</button>`}
else if(s.st=='Đã thanh toán'){const o=owe(s);body+=`<p>Hạn ra cổng không phát sinh phí: <b>${fmt(s.payAt+GRACE*6e4)}</b></p>${o?`<div class="step er"><b>!</b><div><b>Đã quá hạn ra cổng – phát sinh ${vnd(o)}</b><div style="color:var(--mu)">Thời gian đỗ được tính lại đến hiện tại</div></div></div>`:''}<div class="row mt">${o?`<button onclick="reopen('${s.id}')">Thu phí phát sinh</button>`:''}<button class="${o?'s':''}" onclick="receipt('${s.id}')">In lại biên lai</button></div>`}
else if(s.st=='Đã đóng')body+=`<p>Phiên đã đóng lúc <b>${fmt(s.outAt)}</b>${s.exOut?` · ra bằng mở barrier thủ công${s.debt?', chưa thu <b style="color:var(--er)">'+vnd(s.debt)+'</b>':''}`:''}</p>${s.rc?`<div class="mt"><button onclick="receipt('${s.id}')">In lại biên lai</button></div>`:''}`}
return head('Quầy thu ngân','Tra cứu phiên đỗ, tính phí tự động và thu tiền')+`<div class="g g2"><div class="c"><h3>Tra cứu xe</h3><div class="row"><select id="cp"><option value="">Chọn biển số…</option>${S.sess.filter(x=>x.st!='Đã đóng').map(x=>`<option value="${x.id}" ${x.id==cs?'selected':''}>${x.plate} · ${x.lot} (${x.st})</option>`).join('')}</select><button onclick="cs=$('#cp').value||null;R()">Tra cứu</button></div><div class="mt">${body}</div></div>
<div class="c"><h3>Xe chưa thanh toán (${unp.length})</h3>${tbl(['Biển số','Giờ vào','Tạm tính','Trạng thái'],unp.map(x=>[`<a style="cursor:pointer;color:var(--pr)" onclick="cs='${x.id}';R()">${x.plate}</a>`,fmt(x.inAt),vnd(leftOf(x)),x.pend?tag('QR chờ xác nhận','wa'):x.paid?tag('Phát sinh thêm','er'):tag('Chưa thanh toán','wa')]))}<h3 class="mt">Giao dịch QR gần đây</h3>${qrTbl(S.qr.slice(0,5))}</div></div>`};
const qrTbl=L=>tbl(['Mã QR','Biển số','Số tiền','Thời điểm','Kết quả',''],L.map(q=>[q.ref,q.plate,vnd(q.amt),fmt(q.t),tag(q.st=='ok'?'Thành công':q.st=='fail'?'Thất bại':'Chờ xác nhận',q.st=='ok'?'ok':q.st=='fail'?'er':'wa'),q.st=='pending'&&can('pay')?`<button class="s" onclick="cs='${q.id}';go('pay')">Tra soát</button>`:`<small style="color:var(--mu)">${esc(q.msg||'')}${q.rc?' · '+q.rc:''}</small>`]));
window.reopen=id=>{const s=S.sess.find(x=>x.id==id);if(s&&s.st=='Đã thanh toán'&&owe(s)>0){s.st='Đang đỗ';R()}};
window.chg=l=>$('#chg').textContent=vnd(Math.max(0,$('#cash').value-l));
/* Mỗi lần thu tạo 1 biên lai riêng trong S.pays; số tiền phải khớp số còn lại tại thời điểm xác nhận */
const leftOf=s=>Math.max(0,feeOf(s).tot-s.paid);
function finish(s,ch,amt){const f=feeOf(s),t=now(),rc='BL-000'+(++S.rcN);S.pays.push({rc,id:s.id,plate:s.plate,lot:s.lot,inAt:s.inAt,t,amt,ch});s.due=f.tot;s.paid+=amt;s.ch=ch;s.st='Đã thanh toán';s.payAt=t;s.rc=rc;receipt(s.id)}
const payable=(s,l)=>{if(!s||s.st!='Đang đỗ'){toast('Phiên không ở trạng thái chờ thanh toán');R();return false}if(s.pend){toast('Phiên có giao dịch QR chờ xác nhận – tra soát trước khi thu tiếp');R();return false}if(feeOf(s).np){toast('Chưa có khung giá phù hợp – không thể thu');return false}if(leftOf(s)!=l){toast('Số tiền phải thu vừa thay đổi do thời gian đỗ tăng – vui lòng kiểm tra lại');R();return false}return true};
window.cashPay=(id,l)=>{const s=S.sess.find(x=>x.id==id);if(!payable(s,l))return;const c=+$('#cash').value;if(!Number.isFinite(c)||c<l){note('er','Thu tiền mặt chưa đủ',s.plate+' · nhận '+vnd(c||0)+' / cần '+vnd(l));return popup('er','Tiền nhận chưa đủ',`Cần thu <b>${vnd(l)}</b>, mới nhận <b>${vnd(c||0)}</b>.`,['Thu thêm phần còn thiếu rồi xác nhận lại','Hoặc chuyển sang thanh toán QR'])}finish(s,'Tiền mặt',l);note('ok','Thu tiền mặt thành công',s.plate+' · '+vnd(l)+' · '+s.rc)};
/* ok: 1 thành công · 0 ngân hàng từ chối · 2 chưa phản hồi (chờ tra soát) */
window.bank=(id,ok,l)=>{const s=S.sess.find(x=>x.id==id);if(!payable(s,l))return;const ref='QR-'+String(++S.qrN).padStart(4,'0'),q={ref,id,plate:s.plate,amt:l,t:now()};S.qr.unshift(q);
if(ok==1){finish(s,'QR',l);Object.assign(q,{st:'ok',rc:s.rc,msg:'Ngân hàng xác nhận thành công'});note('ok','Thanh toán QR thành công',s.plate+' · '+vnd(l)+' · '+s.rc);return}
if(ok==0){Object.assign(q,{st:'fail',msg:'Ngân hàng từ chối giao dịch'});note('er','Thanh toán QR thất bại',s.plate+' · '+vnd(l)+' · '+ref);R();return popup('er','Thanh toán QR thất bại',`Ngân hàng từ chối giao dịch <b>${ref}</b> (${vnd(l)}). Phiên vẫn chưa thanh toán, barrier lane ra giữ đóng.`,['Tạo lại mã QR cho khách quét lại','Hoặc chuyển sang thu tiền mặt'])}
Object.assign(q,{st:'pending',msg:'Banking Gateway chưa phản hồi'});s.pend=ref;note('wa','QR chờ ngân hàng xác nhận',s.plate+' · '+vnd(l)+' · '+ref);R();popup('wa','Giao dịch đang chờ xác nhận',`Đã gửi <b>${ref}</b> (${vnd(l)}) nhưng ngân hàng chưa phản hồi. Phiên tạm khóa thu tiền để tránh thu trùng.`,['Kiểm tra app ngân hàng của khách hoặc chờ phản hồi','Bấm "Tra soát" để ghi nhận kết quả thành công hoặc thất bại'])};
/* Tra soát giao dịch QR đang chờ: thành công thì ghi biên lai theo thời điểm khách chuyển tiền */
window.qrRes=(ref,ok)=>{const q=S.qr.find(x=>x.ref==ref&&x.st=='pending');if(!q)return toast('Giao dịch không còn ở trạng thái chờ');const s=S.sess.find(x=>x.id==q.id);s.pend=null;
if(ok){const rc='BL-000'+(++S.rcN);S.pays.push({rc,id:s.id,plate:s.plate,lot:s.lot,inAt:s.inAt,t:q.t,amt:q.amt,ch:'QR'});s.paid+=q.amt;s.ch='QR';s.rc=rc;s.payAt=q.t;s.due=feeOf(s,q.t).tot;if(s.st=='Đang đỗ'&&s.paid>=s.due)s.st='Đã thanh toán';Object.assign(q,{st:'ok',rc,msg:'Tra soát: ngân hàng xác nhận thành công'});note('ok','Tra soát QR thành công',s.plate+' · '+vnd(q.amt)+' · '+rc);R();popup('ok','Đã ghi nhận thanh toán',`${ref} · ${vnd(q.amt)} · biên lai <b>${rc}</b>.${owe(s)?' Còn phát sinh '+vnd(owe(s))+' do quá hạn.':''}`)}
else{Object.assign(q,{st:'fail',msg:'Tra soát: giao dịch không thành công'});note('er','Tra soát QR thất bại',s.plate+' · '+vnd(q.amt)+' · '+ref);R();popup('er','Giao dịch không thành công',`${ref} không được ngân hàng ghi nhận. Phiên quay lại trạng thái chưa thanh toán.`,['Tạo mã QR mới hoặc thu tiền mặt'])}};
window.receipt=id=>{const s=S.sess.find(x=>x.id==id),ps=S.pays.filter(x=>x.id==id),y=ps[ps.length-1];if(!y)return toast('Phiên chưa có biên lai');modal(`<h3>Biên lai đã in</h3><div class="rc">CẢNG TCS – BIÊN LAI BÃI ĐỖ\nSố: ${y.rc}\nBiển số : ${s.plate}\nGiờ vào : ${fmt(s.inAt)}\nGiờ TT  : ${fmt(y.t)}\nHình thức: ${y.ch}\nĐã thu  : ${vnd(y.amt)}${ps.length>1?'\nTổng đã thu phiên: '+vnd(s.paid):''}\nCòn lại : 0 đ\nRa cổng trước ${fmt(y.t+GRACE*6e4)} không phát sinh phí</div><div class="row mt"><button onclick="cm();R()">Đóng</button></div>`)};

/* LANE RA */
let outR=null;
P.out=()=>head('Kiểm soát lane ra','Camera AI đọc biển số → đối chiếu phiên vào → kiểm tra thanh toán → barrier')+`<div class="g g2"><div class="c"><h3>Mô phỏng xe tiến vào lane ra</h3><label>Biển số camera đọc được</label><div class="row"><select id="op">${[...new Set(live().map(s=>s.plate).concat('29A-999.99'))].map(p=>`<option>${esc(p)}</option>`).join('')}</select><button onclick="scanOut()">Camera đọc biển số</button></div><p style="color:var(--mu)">Sau khi thanh toán, xe có ${GRACE} phút để ra mà không phát sinh phí. Quá hạn, hệ thống tính lại phí; nếu phí tăng thì xe bị giữ lại. Thử: 50H-135.79 (đã thanh toán, cho ra), 62C-888.66 (quá hạn sau thanh toán), 51C-246.13 (chưa thanh toán), 51D-468.20 (QR chờ xác nhận), 29A-999.99 (không có phiên vào).</p><div class="mt">${pic('lane-out',laneSvg('out'),'Camera lane ra 1')}</div><div style="margin-top:12px">Barrier lane ra</div><div class="gate ${S.lane.out?'open':''}"></div></div><div class="c"><h3>Kết quả xử lý</h3>${outR||waitR('out')}</div></div>`;
window.scanOut=()=>{const p=$('#op').value,s=live().find(x=>x.plate==p);let pass=false,why='',pend=false;let h=st('ok','Camera AI đọc biển số lane ra',plate(p)+' · chụp ảnh biển số và khuôn mặt check-out'),btn='';
if(!s){why='Không có phiên vào tương ứng';note('er','Xe ra không có phiên vào',p);h+=st('er','Không có phiên vào tương ứng','Barrier giữ đóng – bảo vệ kiểm tra thủ công');btn=`<button class="d" onclick="manual('${p}','ra')">Mở barrier thủ công</button>`}
else if(feeOf(s,oweT(s)).np){why='Chưa cấu hình khung giá cho '+s.type;h+=st('er','Không tính được phí đỗ','Bảng giá chưa có khung phù hợp cho '+s.type+' · '+dur(feeOf(s).m)+' – cần quản lý bổ sung bảng giá');btn=`<button class="d" onclick="manual('${p}','ra')">Mở barrier thủ công</button>`}
else{const o=owe(s);h+=st('ok','Đối chiếu phiên vào','Phiên '+s.id+' · vào lúc '+fmt(s.inAt)+' · lô '+s.lot);
h+=st('ok','Hiển thị ảnh tài xế lúc vào / lúc ra','Bảo vệ quan sát trực tiếp trên màn hình, hệ thống không so khớp tự động');
if(o>0&&s.st=='Đã thanh toán'){s.st='Đang đỗ'}
if(s.pend)h+=st('wa','Giao dịch QR chờ ngân hàng xác nhận',s.pend+' – thu ngân cần tra soát trước khi cho xe ra');
h+=st(o?(s.pend?'wa':'er'):'ok','Kiểm tra thanh toán',o?(s.paid?'Còn nợ phát sinh (quá '+GRACE+' phút sau thanh toán): ':'Chưa thanh toán – phải thu ')+vnd(o):'Đã thanh toán đủ (còn lại 0 đ)');
if(!o){pass=true;s.st='Đã đóng';s.outAt=now();s.imgOut=1;const l=lotOf(s);if(l)l.used=true;S.lane.out=1;clearTimeout(S.lane.to);S.lane.to=setTimeout(()=>{S.lane.out=0;if(cur=='out')R()},2500);h+=st('ok','Đạt điều kiện cho ra – tự động mở barrier','Đã ghi giờ ra, lưu ảnh check-out, đóng phiên '+s.id);note('ok','Xe ra thành công',p+' · đóng phiên '+s.id)}
else if(s.pend){why='Chờ ngân hàng xác nhận '+s.pend;pend=true;h+=st('wa','Chờ xác nhận – barrier giữ đóng','Hướng dẫn xe vào làn chờ đến khi có kết quả tra soát');note('wa','Xe ra chờ xác nhận thanh toán',p+' · '+s.pend);btn=can('pay')?`<button onclick="cs='${s.id}';go('pay')">Tra soát tại quầy</button> `:'';btn+=`<button class="d" onclick="manual('${p}','ra')">Mở barrier thủ công</button>`}
else{why='Còn phải thu '+vnd(o)+' · quay lại quầy';h+=st('er','Không đạt – barrier giữ đóng','Cảnh báo bảo vệ: hướng dẫn tài xế quay lại quầy thanh toán');S.alerts.unshift({t:now(),plate:p,owe:o});note('er','Xe bị giữ ở lane ra',p+' · còn phải thu '+vnd(o));btn=`<button class="s" onclick="turn('${p}')">Xe quay lại quầy</button> `;btn+=`<button class="d" onclick="manual('${p}','ra')">Mở barrier thủ công</button>`}}
S.last.out=p;outR=snap('out',p,s?s.type:null,pass,h+(btn?`<div class="row mt">${btn}</div>`:''),{why,pend,nf:!s&&!lotBy(p)});R()};
window.turn=p=>{const s=live().find(x=>x.plate==p);S.exc.unshift({t:now(),who:'baove01',lane:'Lane ra 1',plate:p,why:'Chưa thanh toán đủ, còn '+vnd(owe(s)),kind:'Quay lại quầy thanh toán'});outR=null;cs=s.id;if(can('pay')){go('pay');toast('Đã ghi nhật ký và chuyển sang quầy thu ngân')}else{R();toast('Đã ghi nhật ký – thu ngân sẽ xử lý tại quầy')}};

/* DANH MỤC */
/* m: 1 thành công · 0 lỗi kết nối · 2 phản hồi chậm (chờ 4 giây) */
const syncDone=a=>{S.lots.sy=now();const n=S.lots.filter(l=>l.pend);n.forEach(l=>{l.pend=0;l.ex=1;l.sync='Đã đồng bộ'});Object.assign(a,{ok:true,msg:'OK – '+S.lots.length+' bản ghi'+(n.length?', cập nhật xuất kho '+n.map(l=>l.id).join(', '):'')});note('ok','Đồng bộ COSYS thành công',a.msg)};
window.sync=(m=1)=>{if(S.syncing)return toast('Đang chờ COSYS phản hồi lần đồng bộ trước');const a={t:now(),sys:'COSYS',ip:'10.10.1.5'};S.api.unshift(a);
if(m==0){Object.assign(a,{ok:false,msg:'Timeout 30s – không kết nối được COSYS'});note('er','Đồng bộ COSYS thất bại',a.msg);R();return popup('er','Đồng bộ COSYS thất bại','Không kết nối được COSYS (timeout 30 giây). Danh mục lô hàng giữ nguyên dữ liệu lần đồng bộ trước.',['Kiểm tra kết nối mạng tới 10.10.1.5','Thử đồng bộ lại; lane vào vẫn dùng dữ liệu đã có'])}
if(m==2){Object.assign(a,{ok:null,msg:'Đã gửi yêu cầu, chờ COSYS phản hồi'});S.syncing=a;note('wa','Đồng bộ COSYS đang chờ phản hồi','Yêu cầu lúc '+fmt(a.t));R();toast('Đã gửi yêu cầu – chờ COSYS phản hồi');setTimeout(()=>{S.syncing=null;syncDone(a);a.msg+=' (phản hồi chậm 4 giây)';R();toast('COSYS đã phản hồi – đồng bộ hoàn tất')},4000);return}
syncDone(a);toast('Đã đồng bộ COSYS thành công');R()};

/* GIÁ */
P.prices=()=>head('Bảng giá sân đỗ','Khung giá theo loại xe và thời gian đỗ','<button onclick="edP()">+ Thêm khung giá</button>')+`<div class="c">${tbl(['Mã','Loại xe','Từ (phút)','Đến (phút)','Đơn giá',''],S.prices.map((p,i)=>[p.id,p.type,p.from,p.to>9e4?'∞':p.to,vnd(p.price),`<button class="s" onclick="edP(${i})">Sửa</button> <button class="s" onclick="S.prices.splice(${i},1);R()">Xóa</button>`]))}</div>`;
window.edP=i=>{const p=S.prices[i]||{id:nextId('BG-',S.prices),type:TYPES[0],from:0,to:60,price:0};modal(`<h3>${i>=0?'Sửa':'Thêm'} khung giá</h3><label>Loại xe</label><select id="pt">${TYPES.map(t=>`<option ${t==p.type?'selected':''}>${t}</option>`).join('')}</select><label>Từ (phút)</label><input id="pf" type=number value=${p.from}><label>Đến (phút)</label><input id="pto" type=number value=${p.to}><label>Đơn giá (đ)</label><input id="pp" type=number value=${p.price}><div class="row mt"><button onclick="svP(${i>=0?i:-1},'${p.id}')">Lưu</button><button class="s" onclick="cm()">Hủy</button></div>`)};
window.svP=(i,id)=>{const o={id,type:$('#pt').value,from:+$('#pf').value,to:+$('#pto').value,price:+$('#pp').value};if(![o.from,o.to,o.price].every(Number.isInteger)||o.from<0||o.price<0)return toast('Nhập số nguyên không âm cho thời gian và đơn giá');if(o.to<=o.from)return toast('Khoảng thời gian không hợp lệ');const ov=S.prices.find((x,j)=>j!=i&&x.type==o.type&&o.from<x.to&&x.from<o.to);if(ov)return toast('Trùng khoảng thời gian với khung '+ov.id);i<0?S.prices.push(o):S.prices[i]=o;cm();R();toast('Đã lưu bảng giá')};
P.sur=()=>head('Phụ phí dịch vụ','Phụ phí tự động cộng vào tổng phải thu','<button onclick="edS()">+ Thêm phụ phí</button>')+`<div class="c">${tbl(['Mã','Loại phụ phí','Ngưỡng (phút)','Mức thu','Áp dụng',''],S.sur.map((p,i)=>[p.id,esc(p.name),'> '+p.after,vnd(p.fee),tag(p.on?'Bật':'Tắt',p.on?'ok':''),`<button class="s" onclick="S.sur[${i}].on^=1;R()">${p.on?'Tắt':'Bật'}</button> <button class="s" onclick="S.sur.splice(${i},1);R()">Xóa</button>`]))}</div>`;
window.svS=()=>{const n=$('#sn').value.trim(),a=+$('#sa').value,f=+$('#sf').value;if(!n)return toast('Nhập tên');if(!$('#sa').value||!$('#sf').value||!Number.isInteger(a)||!Number.isInteger(f)||a<0||f<0)return toast('Ngưỡng và mức thu phải là số nguyên không âm');S.sur.push({id:nextId('PP-0',S.sur),name:n,after:a,fee:f,on:1});cm();R();toast('Đã lưu phụ phí')};
window.edS=()=>modal(`<h3>Thêm phụ phí</h3><label>Tên</label><input id="sn"><label>Ngưỡng thời gian (phút)</label><input id="sa" type=number value=180><label>Mức phụ thu (đ)</label><input id="sf" type=number value=50000><div class="row mt"><button onclick="svS()">Lưu</button><button class="s" onclick="cm()">Hủy</button></div>`);

/* QUẢN TRỊ */
const PERM={'Bảo vệ cổng':'Lane vào, lane ra, mở barrier thủ công','Thu ngân quầy':'Tra cứu, thu tiền, in biên lai','Quản lý an ninh':'Xem lịch sử, báo cáo, bảng giá','Quản trị hệ thống':'Toàn quyền, phân quyền, kết nối API'};
P.users=()=>head('Phân quyền người dùng','4 vai trò: bảo vệ, thu ngân, quản lý an ninh, quản trị','<button onclick="edU()">+ Thêm người dùng</button>')+`<div class="g g2"><div class="c">${tbl(['Tài khoản','Họ tên','Vai trò','Trạng thái',''],S.users.map((u,i)=>[esc(u.u),esc(u.n),u.r,tag(u.on?'Hoạt động':'Khóa',u.on?'ok':'er'),`<button class="s" onclick="lkU(${i})">${u.on?'Khóa':'Mở khóa'}</button>`]))}</div><div class="c"><h3>Quyền theo vai trò</h3>${Object.entries(PERM).map(([r,p])=>st('ok',r,p)).join('')}</div></div>`;
window.lkU=i=>{const u=S.users[i];if(u==me)return toast('Không thể khóa tài khoản đang đăng nhập');u.on^=1;R()};
window.svU=()=>{const u=$('#un').value.trim().toLowerCase(),n=$('#uf').value.trim();if(!/^[a-z0-9._]{3,32}$/.test(u))return toast('Tên đăng nhập 3–32 ký tự: chữ thường, số, dấu chấm, gạch dưới');if(S.users.some(x=>x.u==u))return toast('Tên đăng nhập đã tồn tại');if(!n)return toast('Nhập họ tên');S.users.push({u,n,r:$('#ur').value,on:1});cm();R();toast('Đã thêm người dùng')};
window.edU=()=>modal(`<h3>Thêm người dùng</h3><label>Tên đăng nhập</label><input id="un"><label>Họ tên</label><input id="uf"><label>Vai trò</label><select id="ur">${Object.keys(PERM).map(r=>`<option>${r}</option>`).join('')}</select><div class="row mt"><button onclick="svU()">Lưu</button><button class="s" onclick="cm()">Hủy</button></div>`);


/* BÁO CÁO */
P.rev=()=>{const d=[['T2',6.2],['T3',7.1],['T4',5.8],['T5',8.4],['T6',9.3],['T7',7.7],['CN',4.1]],ca=[['Ca sáng',9.8],['Ca chiều',8.6],['Ca đêm',3.2]];
return head('Báo cáo doanh thu','Theo ngày, ca và kênh thanh toán','<button class="s" onclick="toast(\'Đã xuất file Excel\')">Xuất Excel</button><button class="s" onclick="toast(\'Đã xuất file PDF\')">Xuất PDF</button>')+`<div class="g g2"><div class="c"><h3>Doanh thu 7 ngày (triệu đồng)</h3>${bars(d,x=>x.toFixed(1))}</div><div class="c"><h3>Theo ca (triệu đồng)</h3>${bars(ca,x=>x.toFixed(1))}<h3 class="mt">Theo kênh thanh toán</h3>${bars([['QR',14.6],['Tiền mặt',7.0]],x=>x.toFixed(1))}</div></div>`};
P.trf=()=>{const h=[['06h',12],['08h',34],['10h',41],['12h',22],['14h',38],['16h',45],['18h',19]];
return head('Báo cáo lưu lượng xe','Xe ra vào và mở barrier thủ công','<button class="s" onclick="toast(\'Đã xuất báo cáo\')">Xuất báo cáo</button>')+`<div class="g g2"><div class="c"><h3>Lượt xe vào theo khung giờ</h3>${bars(h)}</div><div class="c"><h3>Tổng hợp</h3>${st('ok','Xe vào hôm nay',String(211+S.sess.length))}${st('ok','Xe ra hôm nay','204')}${st(S.exc.filter(e=>e.kind.startsWith('Mở')).length?'wa':'ok','Mở barrier thủ công',S.exc.filter(e=>e.kind.startsWith('Mở')).length+' lượt – cần kiểm tra lý do')}</div></div>`};

/* ===== v3: đăng nhập, phân quyền, màn hình con ===== */
let me=null,lf={q:'',s:''},hf={q:'',a:'',b:'',k:'',g:''},tf='';S.iv=5;S.last={in:'—',out:'—'};
S.dev=[{n:'COSYS',ip:'10.10.1.5',st:'Online'},{n:'Camera AI (ALPR)',ip:'10.10.2.21',st:'Online'},{n:'Radar lane vào',ip:'10.10.2.30',st:'Online'},{n:'Barrier lane ra',ip:'10.10.2.41',st:'Online'},{n:'Banking Gateway',ip:'gw.bank.local',st:'Online'}];
const ALL=MENU.flatMap(g=>g[1].map(x=>x[0]));
S.perm={'Bảo vệ cổng':['in','out','mon','alert'],'Thu ngân quầy':['pay','txn','alert'],'Quản lý an ninh':['in','out','mon','alert','lots','recv','pay','txn','prices','sur','hist','rev','trf'],'Quản trị hệ thống':ALL};
const can=k=>k=='dash'||S.perm[me.r].includes(k),vis=()=>me?MENU.map(([g,a])=>[g,a.filter(x=>can(x[0]))]).filter(x=>x[1].length):[],foot=()=>me?`<h6>Tài khoản</h6><a tabindex=0 onclick="logout()">${esc(me.n)}<br><small>${me.r} – Đăng xuất</small></a>`:'';
window.login=u=>{me=S.users.find(x=>x.u==u);go(vis()[0][1][0][0])};
P.deny=()=>head('Không có quyền truy cập','Vai trò '+me.r+' không được dùng chức năng này. Liên hệ quản trị hệ thống.');
const imgP=p=>pic('plates/'+p,plSvg(p),'Ảnh biển số','s'),imgF=(t,id='x')=>pic('faces/'+id+'-'+(/out/.test(t)?'out':'in'),faceSvg(),t,'s');
const kv=a=>`<table>${a.map(([k,v])=>`<tr><td style="color:var(--mu)">${k}</td><td>${v}</td></tr>`).join('')}</table>`;
window.sessD=id=>{const s=S.sess.find(x=>x.id==id),e=s.outAt||s.payAt||now();modal(`<h3>Phiên ${s.id}</h3><div class="row">${imgP(s.plate)}${imgF('Tài xế – check-in',s.id)}${s.outAt?imgF('Tài xế – check-out',s.id):''}</div>`+kv([['Biển số',s.plate],['Loại xe / Lô hàng',s.type+' / '+s.lot],['Giờ vào',fmt(s.inAt)],['Giờ thanh toán',fmt(s.payAt)],['Giờ ra',fmt(s.outAt)],['Tổng thời gian đỗ',dur(Math.ceil((e-s.inAt)/6e4))],['Đã thu',s.paid?vnd(s.paid)+' ('+s.ch+')':'—'],['Biên lai',S.pays.filter(x=>x.id==s.id).map(x=>x.rc).join(', ')||'—'],['Ngoại lệ',s.exIn?'Vào bằng mở thủ công':s.exOut?'Ra bằng mở thủ công, chưa thu '+vnd(s.debt||0):'Không']])+`<div class="row mt"><button onclick="cm()">Đóng</button></div>`)};
/* Giám sát */
P.mon=()=>{const ln=(n,k,d)=>{const p=S.last[k],l=lotBy(p),op=S.lane[k];return`<div class="c"><h3>${n}</h3>${pic('lane-'+k,laneSvg(k),n+' – camera')}<div class="row mt">${imgP(p)}${imgF('Tài xế')}</div>`+kv([['Radar',tag(op?'Vehicle Present':'Clear',op?'wa':'ok')],['Camera ALPR / góc rộng',tag('Online','ok')],['Barrier',tag(op?'Đang mở':'Đóng',op?'ok':'er')],['Biển số gần nhất',p],['Phân loại phương tiện',l?l.type+' · tải trọng đăng ký 15 tấn':'Chưa phân loại']])+`<div class="row mt"><button class="s" onclick="go('${k}')">Mở màn hình kiểm soát</button><button class="d" onclick="manual('${p}','${d}')" ${p=='—'?'disabled title="Chưa có biển số được đọc"':''}>Mở barrier thủ công</button></div></div>`};
return head('Giám sát camera & radar','Tín hiệu radar, ảnh biển số, chân dung tài xế và trạng thái barrier từng lane')+`<div class="g g2">${ln('Lane vào 1','in','vào')}${ln('Lane ra 1','out','ra')}</div>`};
/* Giao dịch */
P.txn=()=>{const L=S.pays.filter(x=>!tf||x.ch==tf),t=L.reduce((a,x)=>a+x.amt,0);return head('Giao dịch thanh toán','Mốc giờ vào, giờ thanh toán, tổng thời gian đỗ và mã giao dịch')+`<div class="c"><div class="row"><select id="tc"><option value="">Tất cả kênh</option><option ${tf=='QR'?'selected':''}>QR</option><option ${tf=='Tiền mặt'?'selected':''}>Tiền mặt</option></select><button onclick="tf=$('#tc').value;R()">Lọc</button><b>Tổng: ${vnd(t)}</b></div></div><div class="c mt">${tbl(['Mã GD','Biển số','Mã kiện','Giờ vào','Giờ thanh toán','Đỗ','Đã thu','Kênh',''],L.map(x=>[x.rc,x.plate,x.lot,fmt(x.inAt),fmt(x.t),dur(Math.ceil((x.t-x.inAt)/6e4)),vnd(x.amt),x.ch,`<button class="s" onclick="sessD('${x.id}')">Chi tiết</button>`]))}</div><div class="c mt"><h3>Nhật ký giao dịch QR (thành công / thất bại / chờ xác nhận)</h3>${qrTbl(S.qr)}</div>`};
/* Cảnh báo */
P.alert=()=>head('Cảnh báo xe chưa thanh toán','Xe bị giữ barrier ở lane ra và nhật ký quay đầu')+`<div class="c">${tbl(['Thời điểm','Biển số','Còn phải thu','Trạng thái',''],S.alerts.map(a=>{const x=live().find(s=>s.plate==a.plate),o=x?owe(x):0;return[fmt(a.t),a.plate,vnd(a.owe),x?tag(o?'Chờ thanh toán':'Đã thanh toán – cho ra',o?'er':'ok'):tag('Đã xử lý','ok'),x&&o&&can('pay')?`<button class="s" onclick="cs='${x.id}';go('pay')">Chuyển thu ngân</button>`:'']}))}</div><div class="c mt"><h3>Nhật ký quay đầu / quay lại quầy</h3>${tbl(['Thời điểm','Lane','Biển số','Lý do'],S.exc.filter(e=>!e.kind.startsWith('Mở')).map(e=>[fmt(e.t),e.lane,esc(e.plate),esc(e.why)]))}</div>`;
/* Lô hàng + đồng bộ */
P.lots=()=>{const q=lf.q.toLowerCase(),L=S.lots.filter(l=>(l.plate+l.id).toLowerCase().includes(q)&&(!lf.s||(lf.s=='ok')==!!(l.ex&&l.reg&&!l.used)));return head('Danh mục lô hàng','Đồng bộ từ COSYS, chu kỳ '+S.iv+' phút/lần','<button onclick="sync(1)">Đồng bộ ngay</button><button class="s" onclick="sync(0)">Giả lập lỗi</button><button class="s" onclick="sync(2)">Giả lập phản hồi chậm</button><button class="s" onclick="ivM()">Cấu hình đồng bộ</button>')+`<div class="c"><div class="row"><input id="lq" placeholder="Mã lô / biển số" value="${esc(lf.q)}"><select id="ls"><option value="">Tất cả</option><option value="ok" ${lf.s=='ok'?'selected':''}>Đủ điều kiện vào</option><option value="no" ${lf.s=='no'?'selected':''}>Chưa đủ điều kiện</option></select><button onclick="lf={q:$('#lq').value,s:$('#ls').value};R()">Lọc</button></div></div><div class="c mt">${tbl(['Mã lô','Biển số','Loại xe','Xuất kho','Đăng ký web','Đồng bộ lúc',''],L.map(l=>[l.id,l.plate,l.type,tag(l.used?'Đã nhận xong':l.ex?'Đã xuất':l.pend?'Chờ COSYS':'Chưa xuất',l.used||l.ex?'ok':'wa'),tag(l.reg?'Đã đăng ký':'Chưa đăng ký',l.reg?'ok':'wa'),fmt(S.lots.sy||now()-3e5),`<button class="s" onclick="lotD('${l.id}')">Chi tiết</button>`]))}</div><div class="c mt"><h3>Nhật ký đồng bộ COSYS</h3>${tbl(['Thời gian','Kết quả','Chi tiết'],S.api.filter(a=>a.sys=='COSYS').slice(0,5).map(a=>[fmt(a.t),apiTag(a),a.msg]))}</div>`};
window.ivM=()=>modal(`<h3>Cấu hình đồng bộ COSYS</h3><label>Chu kỳ truy vấn API</label><select id="iv">${[1,5,10,15].map(v=>`<option ${v==S.iv?'selected':''} value=${v}>${v} phút/lần</option>`).join('')}</select><div class="row mt"><button onclick="S.iv=+$('#iv').value;cm();R();toast('Đã lưu chu kỳ đồng bộ')">Lưu</button><button class="s" onclick="cm()">Hủy</button></div>`);
window.lotD=id=>{const l=S.lots.find(x=>x.id==id),s=S.sess.find(x=>x.lot==id);modal(`<h3>Lô hàng ${l.id}</h3>`+kv([['Biển số',esc(l.plate)],['Loại xe',l.type],['Chủ hàng',esc(l.owner)],['Tài xế',esc(l.driver)],['Xuất kho',l.ex?'Đã xuất':l.pend?'Chờ COSYS phản hồi':'Chưa xuất'],['Đăng ký web',l.reg?'Đã đăng ký':'Chưa đăng ký'],['Điều kiện vào',l.ex&&l.reg&&!l.used?'Đạt':'Không đạt'],['Phiên bãi',s?s.id+' – '+s.st:'Chưa có']])+`<div class="row mt">${s?`<button class="s" onclick="cm();sessD('${s.id}')">Xem phiên</button>`:''}<button onclick="cm()">Đóng</button></div>`)};
/* Nhận hàng */
P.recv=()=>head('Thông tin nhận hàng','Tài xế, chủ hàng và tình trạng đăng ký (từ web đăng ký lấy hàng)','<button onclick="recvE(-1)">+ Đăng ký nhận hàng (mô phỏng web)</button>')+`<div class="c">${tbl(['Lô hàng','Biển số','Tài xế','Chủ hàng','Đăng ký','Đủ điều kiện vào',''],S.lots.map((l,i)=>[l.id,esc(l.plate),esc(l.driver),esc(l.owner),tag(l.reg?'Đã đăng ký':'Chưa đăng ký',l.reg?'ok':'wa'),l.reg&&l.ex&&!l.used?tag('Đạt','ok'):tag('Không đạt','er'),`<button class="s" onclick="recvV(${i})">Xem</button>`]))}</div>`;
window.recvV=i=>{const l=S.lots[i],f=(t,v)=>`<label>${t}</label><input value="${esc(v)}" readonly disabled>`;modal(`<h3>Thông tin nhận hàng ${l.id}</h3><p style="color:var(--mu)">Dữ liệu đồng bộ từ web đăng ký lấy hàng và COSYS, chỉ được xem.</p>`+f('Biển số',l.plate)+f('Loại xe',l.type)+f('Tài xế',l.driver)+f('Chủ hàng',l.owner)+f('Đăng ký web',l.reg?'Đã đăng ký':'Chưa đăng ký')+f('Xuất kho (COSYS)',l.ex?'Đã xuất':'Chưa xuất')+f('Đủ điều kiện vào',l.reg&&l.ex&&!l.used?'Đạt':'Không đạt')+`<div class="row mt"><button onclick="cm()">Đóng</button></div>`)};
window.recvE=i=>{const l=S.lots[i]||{plate:'',type:TYPES[0],ex:0,reg:1,driver:'',owner:''},o=(a,v)=>a.map(x=>`<option value="${x[0]}" ${x[0]==v?'selected':''}>${x[1]}</option>`).join('');modal(`<h3>${i>=0?'Sửa '+l.id:'Đăng ký nhận hàng mới'}</h3><label>Biển số</label><input id="rp" value="${esc(l.plate)}" placeholder="51C-123.45"><label>Loại xe</label><select id="rt">${TYPES.map(t=>`<option ${t==l.type?'selected':''}>${t}</option>`).join('')}</select><label>Tài xế</label><input id="rd" value="${esc(l.driver)}"><label>Chủ hàng</label><input id="ro" value="${esc(l.owner)}"><label>Đăng ký web</label><select id="rr">${o([[1,'Đã đăng ký'],[0,'Chưa đăng ký']],l.reg)}</select><label>Xuất kho (mô phỏng dữ liệu COSYS)</label><select id="rx">${o([[1,'Đã xuất'],[0,'Chưa xuất']],l.ex)}</select><div class="row mt"><button onclick="svR(${i})">Lưu</button><button class="s" onclick="cm()">Hủy</button></div>`)};
window.svR=i=>{const p=$('#rp').value.trim().toUpperCase();if(!p)return toast('Nhập biển số');if(!PLATE_RE.test(p))return toast('Biển số không đúng định dạng, ví dụ 51C-123.45');const o=Object.assign(S.lots[i]||{id:nextId('LH-',S.lots,2601),sync:'Đã đồng bộ'},{plate:p,type:$('#rt').value,driver:$('#rd').value.trim()||'—',owner:$('#ro').value.trim()||'—',reg:+$('#rr').value,ex:+$('#rx').value});if(i<0)S.lots.push(o);cm();R();toast('Đã lưu – lane vào dùng dữ liệu mới ngay');};
/* Lịch sử */
P.hist=()=>{const q=hf.q.toLowerCase(),a=hf.a?new Date(hf.a+'T00:00').getTime():0,b=hf.b?new Date(hf.b+'T00:00').getTime()+864e5:9e15,ss=S.sess.filter(x=>x.plate.toLowerCase().includes(q)&&x.inAt>=a&&x.inAt<b),ee=S.exc.filter(e=>e.plate.toLowerCase().includes(q)&&e.t>=a&&e.t<b&&(!hf.k||e.kind==hf.k)&&(!hf.g||e.who==hf.g)),ks=[...new Set(S.exc.map(e=>e.kind))],gs=[...new Set(S.exc.map(e=>e.who))],op=(l,v)=>l.map(x=>`<option ${x==v?'selected':''}>${x}</option>`).join('');
return head('Lịch sử giám sát & ngoại lệ','Tra cứu ảnh vào/ra, thanh toán và mở barrier thủ công')+`<div class="c"><div class="row"><input id="hq" placeholder="Biển số" value="${esc(hf.q)}"><input id="ha" type=date value="${hf.a}"><input id="hb" type=date value="${hf.b}"><select id="hk"><option value="">Mọi loại ngoại lệ</option>${op(ks,hf.k)}</select><select id="hg"><option value="">Mọi mã bảo vệ</option>${op(gs,hf.g)}</select><button onclick="hf={q:$('#hq').value,a:$('#ha').value,b:$('#hb').value,k:$('#hk').value,g:$('#hg').value};R()">Tìm</button><button class="s" onclick="hf={q:'',a:'',b:'',k:'',g:''};R()">Xóa lọc</button></div></div><div class="c mt"><h3>Lịch sử vào/ra & thanh toán (${ss.length})</h3>${tbl(['Phiên','Biển số','Vào','Ra','Thanh toán','Kênh','Trạng thái',''],ss.map(x=>[x.id,esc(x.plate),fmt(x.inAt),fmt(x.outAt),x.paid?vnd(x.paid):'—',x.ch||'—',tag(x.st)+(x.exIn||x.exOut?' '+tag('Ngoại lệ','er'):''),`<button class="s" onclick="sessD('${x.id}')">Xem ảnh & chi tiết</button>`]))}</div><div class="c mt"><h3>Nhật ký ngoại lệ (${ee.length})</h3>${tbl(['Thời điểm','Loại','Lane','Biển số','Mã bảo vệ','Lý do',''],ee.map(e=>[fmt(e.t),e.kind,e.lane,esc(e.plate),esc(e.who),esc(e.why),`<button class="s" onclick="excD(${S.exc.indexOf(e)})">Xem ảnh</button>`]))}</div>`};
window.excD=i=>{const e=S.exc[i];modal(`<h3>Sự kiện ngoại lệ</h3><div class="row">${imgP(e.plate)}${imgF('Ảnh khi kích hoạt')}</div>`+kv([['Loại',e.kind],['Thời điểm',fmt(e.t)],['Lane',e.lane],['Mã bảo vệ',esc(e.who)],['Lý do',esc(e.why)]])+`<div class="row mt"><button onclick="cm()">Đóng</button></div>`)};
/* API */
P.api=()=>head('Kết nối API','Trạng thái tích hợp COSYS, Camera AI, radar, barrier và Banking Gateway')+`<div class="g g4">${S.dev.map((d,i)=>`<div class="c k"><b style="font-size:16px">${d.n}</b><span>${d.ip}</span><div>${tag(d.st,d.st=='Online'?'ok':'er')}</div><div class="row mt"><button class="s" onclick="tst(${i},1)">Kiểm tra</button><button class="s" onclick="tst(${i},0)">Giả lập lỗi</button></div></div>`).join('')}</div><div class="c mt"><h3>Nhật ký gọi API</h3>${tbl(['Thời gian','Hệ thống','IP','Kết quả','Chi tiết'],S.api.map(a=>[fmt(a.t),a.sys,a.ip,apiTag(a),a.msg]))}</div>`;
window.tst=(i,ok)=>{const d=S.dev[i];d.st=ok?'Online':'Error';S.api.unshift({t:now(),sys:d.n,ip:d.ip,ok:!!ok,msg:ok?'Ping OK – 42 ms':'Timeout 30s'});note(ok?'ok':'er',ok?'Kết nối '+d.n+' bình thường':d.n+' mất kết nối',d.ip+' · '+(ok?'Ping OK – 42 ms':'Timeout 30s'));R();toast(ok?'Kết nối '+d.n+' bình thường':'Cảnh báo: '+d.n+' mất kết nối')};
/* Phân quyền + báo cáo */
const _u=P.users;P.users=()=>_u()+`<div class="c mt"><h3>Ma trận phân quyền theo chức năng</h3>${tbl(['Chức năng',...Object.keys(PERM)],MENU.flatMap(g=>g[1]).map(([k,n])=>[n,...Object.keys(PERM).map((r,j)=>`<input type=checkbox ${S.perm[r].includes(k)?'checked':''} ${j==3?'disabled':''} onchange="tp(${j},'${k}')">`)]))}</div>`;
window.tp=(j,k)=>{const a=S.perm[Object.keys(PERM)[j]],i=a.indexOf(k);i<0?a.push(k):a.splice(i,1);R();toast('Đã cập nhật quyền – áp dụng ngay')};
const _r=P.rev;P.rev=()=>{const p=S.pays,f=c=>vnd(p.filter(x=>x.ch==c).reduce((a,x)=>a+x.amt,0));return _r()+`<div class="c mt"><h3>Chi tiết giao dịch trong phiên làm việc</h3><p>QR: <b>${f('QR')}</b> · Tiền mặt: <b>${f('Tiền mặt')}</b></p>${tbl(['Biên lai','Biển số','Kênh','Số tiền','Giờ thu'],p.map(x=>[x.rc,x.plate,x.ch,vnd(x.amt),fmt(x.t)]))}</div>`};
const _t=P.trf;P.trf=()=>{const k={};S.exc.forEach(e=>k[e.kind]=(k[e.kind]||0)+1);return _t()+`<div class="c mt"><h3>Thống kê ngoại lệ theo loại</h3>${bars(Object.entries(k))}</div>`};

window.logout=()=>{me=null;inR=null;outR=null;cs=null;go('dash')};

/* ===== v4: giao diện sáng/tối, thương hiệu, ảnh thực tế ===== */
const isDark=()=>document.documentElement.dataset.theme?document.documentElement.dataset.theme=='dark':matchMedia('(prefers-color-scheme:dark)').matches;
window.tt=()=>{const t=isDark()?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('tcs-theme',t)}catch(e){}R()};
const pic=(slot,fb,cap,cls='')=>`<figure class="pic ${cls}">${CFG.photos?`<img src="assets/img/photos/${slot}.jpg" alt="${cap}" data-fb="${fb.replace(/"/g,'&quot;')}" onerror="this.outerHTML=this.dataset.fb">`:fb}<figcaption>${cap}</figcaption></figure>`;
const plSvg=p=>`<svg viewBox="0 0 150 90"><rect width="150" height="90" fill="#232b3d"/><rect y="66" width="150" height="24" fill="#0f1420"/><rect x="14" y="26" width="122" height="36" rx="5" fill="#f2c530" stroke="#222" stroke-width="2"/><circle cx="22" cy="44" r="2" fill="#555"/><circle cx="128" cy="44" r="2" fill="#555"/><text x="75" y="52" text-anchor="middle" font-family="Arial,sans-serif" font-weight="700" font-size="19" fill="#111" letter-spacing="1">${p}</text></svg>`;
