const heroH=()=>`<div class="hero hero-main"><img src="${IMG.banner}" alt="Máy bay Vietnam Airlines đang xếp container hàng hóa ULD tại sân đỗ"><div><b>TCS – Dịch vụ Hàng hóa Tân Sơn Nhất</b><br>Hệ thống quản lý an ninh cổng lane vào / lane ra khu vực nhận hàng · 46–48 Hậu Giang, TP.HCM</div><small class="cr">Ảnh: Bahnfrend / Wikimedia Commons, CC BY-SA 4.0</small></div>`;
const RIC={'Bảo vệ cổng':'BV','Thu ngân quầy':'TN','Quản lý an ninh':'QL','Quản trị hệ thống':'QT'};
P.login=()=>`<div class="home"><section class="home-hero"><img src="${IMG.banner}" alt="Máy bay Vietnam Airlines đang xếp container hàng hóa ULD tại sân đỗ"><div class="home-in"><span class="logobox"><img src="${IMG.logo}" alt="TCS – Experience Beyond Cargo"></span><div class="home-txt"><span class="home-k">Dịch vụ Hàng hóa Tân Sơn Nhất</span><h1>Hệ thống quản lý an ninh cổng</h1><p>Kiểm soát lane vào / lane ra khu vực nhận hàng · 46–48 Hậu Giang, TP.HCM</p><ul class="home-f">${[['Lane vào','Radar, Camera AI, đối chiếu COSYS'],['Thanh toán','Tính phí đỗ, VietQR / VNPay'],['Lane ra','Kiểm tra phí, mở barrier'],['Báo cáo','Doanh thu và lưu lượng xe']].map(([a,b])=>`<li><b>${a}</b><span>${b}</span></li>`).join('')}</ul></div></div><small class="cr">Ảnh: Bahnfrend / Wikimedia Commons, CC BY-SA 4.0</small></section>
<section class="home-login"><div class="home-bar"><span class="home-badge">Bản demo</span><button class="s" onclick="tt()">◐ Sáng/Tối</button></div><h2>Đăng nhập</h2><p class="home-sub">Chọn tài khoản để vào theo vai trò. Bản demo không cần mật khẩu, menu thay đổi theo quyền.</p><div class="roles">${S.users.filter(u=>u.on).map(u=>`<button class="role" onclick="login('${u.u}')"><span class="av">${RIC[u.r]||esc(u.n[0])}</span><span class="rt"><b>${esc(u.n)}</b><small>${u.r} · ${esc(u.u)}</small></span><span class="ra" aria-hidden="true">›</span></button>`).join('')}</div><p class="home-ft">© TCS – HTQLAN · Hệ thống quản lý an ninh cổng</p></section></div>`;
go(location.hash.slice(1)&&P[location.hash.slice(1)]?location.hash.slice(1):'dash');
